python3 << 'EOF'
import json

with open('/tmp/alpha_decomposition_results.json', 'r') as f:
    data = json.load(f)

print("\n" + "="*80)
print("FINAL ALPHA DECOMPOSITION RESULTS - KEY METRICS")
print("="*80 + "\n")

print("CUMULATIVE RETURNS (60-day):")
for k, v in data['cumulative_returns'].items():
    if isinstance(v, (int, float)):
        print(f"  {k:.<50} {v:>10.2f}%")
    else:
        print(f"  {k:.<50} {v}")

print("\nATTRIBUTION ANALYSIS:")
for k, v in data['attribution'].items():
    print(f"  {k:.<50} {v:>10.2f}%")

print("\nVOLATILITY METRICS:")
for k, v in data['volatility_metrics'].items():
    if isinstance(v, float):
        if 'pct' in k.lower() or 'beta' in k.lower():
            print(f"  {k:.<50} {v:>10.2f}")
        else:
            print(f"  {k:.<50} {v:>10.6f}")

print("\nALPHA CONSISTENCY:")
for k, v in data['alpha_consistency'].items():
    if isinstance(v, (int, float)):
        if 'metric' in k or 'herfindahl' in k:
            print(f"  {k:.<50} {v:>10.2f}")
        elif 'pct' in k.lower():
            print(f"  {k:.<50} {v:>10.2f}%")
        else:
            print(f"  {k:.<50} {v:>10.0f}")
    else:
        print(f"  {k:.<50} {str(v):>10}")

print("\nTOP ALPHA CONTRIBUTORS:")
for i, pos in enumerate(data['stock_level_analysis']['top_alpha_contributors'][:5], 1):
    print(f"  {i}. {pos['ticker']:6} α={pos['alpha_pct']:>7.2f}%  β={pos['beta']:>6.2f}  weight={pos['weight_pct']:>6.2f}%")

print("\n" + "="*80)
EOF
